OLCU = re.compile(r"(\d{2,3}(?:[.,]\d)?)\s*[xX×*]\s*(\d{2,4}(?:[.,]\d)?)")


def olculeri_oku(apps, schema_editor):
    """Eski siparişlerde ürün açıklamasındaki '160X230' gibi ölçüyü en/boy alanlarına taşır (m²'ye dokunmaz)."""
    Siparis = apps.get_model("uretim", "Siparis")
    for s in Siparis.objects.filter(en_cm__isnull=True):
        eslesme = OLCU.search(s.urun or "")
        if not eslesme:
            continue
        en, boy = (Decimal(x.replace(",", ".")) for x in eslesme.groups())
        guncel = {"en_cm": en, "boy_cm": boy}
        if s.toplam_m2 is None:
            guncel["toplam_m2"] = (en * boy * (s.adet or 1) / 10000).quantize(Decimal("0.01"))
        Siparis.objects.filter(pk=s.pk).update(**guncel)


